import { useCallback, useState } from 'react';
import { AiActions } from '../../../../Services/_actions/Ai/ai.actions.ts';
import { COLUMN_MODAL } from '../constants/columnModalKeys';
import { getRawLead } from '../utils/recordInlineEditUtils';

function normalizeTranscriptList(data) {
  if (Array.isArray(data)) return data;
  if (data && typeof data === 'object') return [data];
  return [];
}

export default function useColumnModals() {
  const [activeModal, setActiveModal] = useState(null);
  const [selectedRow, setSelectedRow] = useState(null);
  const [audioTranscriptList, setAudioTranscriptList] = useState([]);
  const [audioLoading, setAudioLoading] = useState(false);

  const openAudioSummary = useCallback(async (row) => {
    const rawLead = getRawLead(row);
    setSelectedRow(rawLead);
    setActiveModal(COLUMN_MODAL.AUDIO_SUMMARY);
    setAudioLoading(true);

    try {
      const aiActions = AiActions();
      const data = await aiActions.getLeadTranscript(rawLead?.lead_id);
      setAudioTranscriptList(normalizeTranscriptList(data));
    } catch {
      setAudioTranscriptList([]);
    } finally {
      setAudioLoading(false);
    }
  }, []);

  const openAiChat = useCallback((row) => {
    setSelectedRow(getRawLead(row));
    setActiveModal(COLUMN_MODAL.AI_CHAT);
  }, []);

  const closeColumnModal = useCallback(() => {
    setActiveModal(null);
    setSelectedRow(null);
    setAudioTranscriptList([]);
    setAudioLoading(false);
  }, []);

  return {
    selectedRow,
    audioTranscriptList,
    setAudioTranscriptList,
    audioLoading,
    openAudioSummary,
    openAiChat,
    closeColumnModal,
    isAudioSummaryOpen: activeModal === COLUMN_MODAL.AUDIO_SUMMARY,
    isAiChatOpen: activeModal === COLUMN_MODAL.AI_CHAT,
  };
}
