import React, { useCallback, useMemo, useRef } from 'react';

const LeadChatTemplateSyncContext = React.createContext(null);

export function LeadChatTemplateSyncProvider({ children }) {
  const handlerRef = useRef(null);

  const registerTemplateSendSync = useCallback((handler) => {
    handlerRef.current = handler ?? null;
  }, []);

  const notifyTemplateSendResults = useCallback((payload) => {
    handlerRef.current?.(payload);
  }, []);

  const value = useMemo(
    () => ({
      registerTemplateSendSync,
      notifyTemplateSendResults,
    }),
    [registerTemplateSendSync, notifyTemplateSendResults],
  );

  return (
    <LeadChatTemplateSyncContext.Provider value={value}>
      {children}
    </LeadChatTemplateSyncContext.Provider>
  );
}

export function useLeadChatTemplateSync() {
  const ctx = React.useContext(LeadChatTemplateSyncContext);
  if (!ctx) {
    throw new Error('useLeadChatTemplateSync must be used within LeadChatTemplateSyncProvider');
  }
  return ctx;
}

export function useLeadChatTemplateSyncOptional() {
  return React.useContext(LeadChatTemplateSyncContext);
}
