import React, { useEffect, useMemo, useState } from 'react';
import { Box } from '@mui/material';
import TemplateSendPreview from '../../../whatsapp-templates/components/send/TemplateSendPreview';
import { getLeadTemplateHeaderFormat } from '../utils/leadTemplateHeaderSend';

function resolveDocumentDisplayName(mediaUrl, headerFile, template) {
  if (headerFile?.name) return headerFile.name;
  const fromMeta = template?.media?.headerFilename;
  if (fromMeta) return fromMeta;
  if (!mediaUrl) return 'Header document';
  const raw = mediaUrl.split('/').pop()?.split('?')[0] || 'Header document';
  try {
    const decoded = decodeURIComponent(raw);
    const underscore = decoded.indexOf('_');
    if (underscore > 0 && underscore < decoded.length - 1) {
      const tail = decoded.slice(underscore + 1);
      if (tail.includes('.')) return tail;
    }
    return decoded;
  } catch {
    return raw;
  }
}

export default function LeadSendTemplatePreviewPanel({
  template,
  bodyParams = [],
  headerFile = null,
  useTemplateHeaderMedia = false,
}) {
  const headerFormat = getLeadTemplateHeaderFormat(template);
  const [objectUrl, setObjectUrl] = useState('');

  useEffect(() => {
    if (!headerFile) {
      setObjectUrl('');
      return undefined;
    }
    const url = URL.createObjectURL(headerFile);
    setObjectUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [headerFile]);

  const headerMediaUrl = useMemo(() => {
    if (objectUrl) return objectUrl;
    if (useTemplateHeaderMedia && template?.media?.header) {
      return template.media.header;
    }
    return '';
  }, [objectUrl, template, useTemplateHeaderMedia]);

  const previewTemplate = useMemo(() => {
    if (!template) return template;
    if (!headerFormat || headerFormat === 'TEXT') return template;
    if (!headerMediaUrl) {
      return {
        ...template,
        media: { ...(template.media || {}), header: '' },
      };
    }
    return {
      ...template,
      media: {
        ...(template.media || {}),
        header: headerMediaUrl,
        headerFilename: resolveDocumentDisplayName(headerMediaUrl, headerFile, template),
      },
    };
  }, [headerFile, headerFormat, headerMediaUrl, template]);

  if (!template) return null;

  return (
    <Box sx={{ minWidth: 0, width: '100%' }}>
      <TemplateSendPreview template={previewTemplate} bodyParams={bodyParams} />
    </Box>
  );
}
