import {
  canStartLeadChatSession,
  isLeadChatSessionActive,
} from './leadChatSessionRules';
import { userOwnsChat } from '../../../../intervene/utils/chatOwnership';
import { getLastActiveFromUser, isSessionExpired } from './leadChatSessionWindow';

/** @typedef {'active' | 'idle' | 'expired' | 'locked'} LeadChatComposerMode */

export function getLeadChatComposerMode(user, currentUserId = null) {
  const lastActive = getLastActiveFromUser(user);
  if (lastActive && isSessionExpired(lastActive)) return 'expired';

  if (isLeadChatSessionActive(user)) {
    if (userOwnsChat(user, currentUserId)) return 'active';
    return 'locked';
  }

  if (canStartLeadChatSession(user, currentUserId)) return 'idle';
  return 'idle';
}

export function isComposerExpired(mode) {
  return mode === 'expired';
}

export function isComposerIdle(mode) {
  return mode === 'idle';
}

export function isComposerLocked(mode) {
  return mode === 'locked';
}

export function isComposerActive(mode) {
  return mode === 'active';
}

export function canComposeFreeForm(mode) {
  return mode === 'active';
}

/** Open attach menu for free-form (active), template-only (idle/expired), or both. */
export function canOpenComposerAttachMenu(mode, canSendTemplate = false) {
  if (canComposeFreeForm(mode)) return true;
  if (isComposerExpired(mode) && canSendTemplate) return true;
  if (isComposerIdle(mode) && canSendTemplate) return true;
  return false;
}

export function canSendTemplateFromComposer(mode, canSendTemplate = false) {
  if (!canSendTemplate) return false;
  if (isComposerLocked(mode)) return false;
  return isComposerIdle(mode) || isComposerExpired(mode) || canComposeFreeForm(mode);
}
