export function getRawLead(row) {
  return row?._rawLead ?? row ?? null;
}

export function getRecordMongoId(row) {
  return row?._mongoId ?? getRawLead(row)?.id ?? row?.id ?? '';
}

export function getFieldDataFromRow(row, keyName) {
  const rawLead = getRawLead(row);
  if (!rawLead || !keyName) return null;

  if (Array.isArray(rawLead.data)) {
    return rawLead.data.find((entry) => entry?.key_name === keyName) ?? null;
  }

  return null;
}

export function getParentStatusConfig(row, parentKey) {
  const fieldData = getFieldDataFromRow(row, parentKey);
  return fieldData?.status_config ?? null;
}

export function buildEntityQueryParamsForRow(field, rowData) {
  if (!Array.isArray(field?.query_parameter) || field.query_parameter.length === 0) {
    return [];
  }

  const rawLead = getRawLead(rowData) ?? rowData;
  const formDataArr = rawLead?.data ?? [];

  return field.query_parameter.map((param) => {
    const findValue =
      formDataArr.find(
        (entry) =>
          entry?.alias_name === param?.param
          || entry?.key_name === param?.param
          || entry?.key_name === param?.param_key_name
      ) ?? null;

    let paramValue = '';
    let entity_record_id = '';

    if (param?.param === 'global_phone_number') {
      paramValue = rawLead?.phone_number || '';
    } else if (findValue?.entity_data?._id) {
      entity_record_id = findValue.entity_data._id ?? '';
      paramValue = findValue?.value?.value ?? findValue?.value ?? '';
    } else {
      paramValue = findValue?.value ?? '';
    }

    return {
      matched_with: param?.matched_with || '',
      param: param?.param || '',
      ...(paramValue !== '' && paramValue != null ? { paramValue } : {}),
      ...(entity_record_id ? { entity_record_id } : {}),
      ...(param?.entity_form_field ? { entity_form_field: param.entity_form_field } : {}),
    };
  });
}

export function getDependentEntityFieldKeys(parentField, formItems = []) {
  const items = Array.isArray(formItems)
    ? formItems
    : Object.values(formItems ?? {}).filter(Boolean);
  const parentKey = parentField?.key_name;
  if (!parentKey) return new Set();

  const knownParentNames = new Set(
    [parentField.key_name, parentField.alias_name].filter(Boolean)
  );
  const dependentKeys = new Set();
  let foundDependent = true;

  while (foundDependent) {
    foundDependent = false;

    items.forEach((item) => {
      const key = item?.key_name;
      if (
        !key
        || key === parentKey
        || dependentKeys.has(key)
        || item?.key_type !== 'ENTITY'
      ) {
        return;
      }

      const dependsOnKnownParent = (item?.query_parameter ?? []).some((parameter) => {
        const mappedParent = items.find(
          (candidate) =>
            candidate?.key_name === parameter?.param
            || candidate?.alias_name === parameter?.param
        );

        return knownParentNames.has(parameter?.param)
          || knownParentNames.has(parameter?.param_key_name)
          || knownParentNames.has(mappedParent?.key_name);
      });

      if (dependsOnKnownParent) {
        dependentKeys.add(key);
        knownParentNames.add(key);
        if (item?.alias_name) knownParentNames.add(item.alias_name);
        foundDependent = true;
      }
    });
  }

  return dependentKeys;
}

export function buildLeadPayloadForEntityUpdate(rowData, updatedEntries = [], leadFormId) {
  const rawLead = getRawLead(rowData) ?? rowData ?? {};
  const parsedFormId = Number.parseInt(String(leadFormId ?? ''), 10);

  const payload = {
    area: rawLead?.area || '',
    city: rawLead?.city || '',
    lead_id: rawLead?.lead_id || '',
    leads_form_entries: [],
    phone_number: rawLead?.phone_number || '',
    supplier_id: rawLead?.supplier_id || '',
    supplier_name: rawLead?.supplier_name || '',
    leads_form_id: Number.isNaN(parsedFormId) ? '' : parsedFormId,
    parent_id: { lead_id: rawLead?.parent_id?.lead_id || '' },
  };

  payload.leads_form_entries = (updatedEntries ?? []).map((item) => ({
    key_name: item?.key_name,
    value: item?.entity_data?.value ? item?.entity_data?.value ?? '' : item?.value ?? '',
    ...(Object.prototype.hasOwnProperty.call(item ?? {}, 'entity_data')
      ? { entity_data: item.entity_data ?? null }
      : {}),
    ...(item?.status_config ? { status_config: item?.status_config ?? null } : {}),
  }));

  return payload;
}

export function buildClearLinkedSubStatusPayloads(row, fieldMeta, formItems = []) {
  if (fieldMeta?.statusOption !== 'is_status') {
    return [];
  }

  const recordId = getRecordMongoId(row);
  const parentKey = fieldMeta?.key_name;
  if (!recordId || !parentKey) {
    return [];
  }

  const items = Array.isArray(formItems) ? formItems : Object.values(formItems ?? {});

  return items
    .filter(
      (item) =>
        item?.statusOption === 'is_sub_status'
        && item?.status_parent_key === parentKey
    )
    .map((subField) => {
      const fieldData = getFieldDataFromRow(row, subField.key_name);
      const existingSubStatusId = fieldData?.status_config?.sub_status_id;
      if (!existingSubStatusId) {
        return null;
      }

      return {
        id: recordId,
        sub_status_name: '',
        sub_status_id: '',
        status_name: '',
        status_id: '',
        type_of_status: subField.key_name,
      };
    })
    .filter(Boolean);
}

export function buildInlineStatusPayload(row, selected, fieldMeta = {}) {
  const recordId = getRecordMongoId(row);
  const fieldData = getFieldDataFromRow(row, fieldMeta.key_name);
  const isSubStatus = fieldMeta.statusOption === 'is_sub_status';

  if (isSubStatus) {
    return {
      id: recordId,
      sub_status_name: selected?.name ?? '',
      status_name: selected?.status_name || '',
      status_id: selected?.status_id || '',
      type_of_status: selected?.type_of_status ?? fieldData?.key_name ?? fieldMeta.key_name ?? '',
      sub_status_id: selected?.sub_status_id || '',
    };
  }

  return {
    id: recordId,
    status: selected?.status_name || '',
    status_name: selected?.status_name || '',
    status_id: selected?.status_id || '',
    type_of_status: selected?.type_of_status || fieldMeta.key_name || '',
  };
}

export function buildOptionColorsByAlias(formItems = []) {
  const items = Array.isArray(formItems)
    ? formItems
    : Object.values(formItems ?? {}).filter(Boolean);

  return items.reduce((map, field) => {
    const alias = field?.key_name;
    if (alias && field?.option_colors) {
      map[alias] = field.option_colors;
    }
    return map;
  }, {});
}

export function isFieldReadOnly(fieldMeta, canEdit) {
  if (!canEdit) return true;
  return fieldMeta?.access_level === 'view';
}
