import {
  groupLeadItems,
  staticLeadTableColumns,
  updateDataWithFieldPermissions,
} from '../../../../components/Leads/DynamicFormFields/helper.ts';
import { isLeadIdField } from '../../../intervene/utils/leadFormFields';
import { normalizeFormItems } from './dynamicFilterUtils';

export function sortRecordFieldsByOrder(fields = []) {
  return [...fields].sort((a, b) => {
    const orderA = a?.order_id != null && a?.order_id !== '' ? Number(a.order_id) : (Number(a?.item_id) || 0);
    const orderB = b?.order_id != null && b?.order_id !== '' ? Number(b.order_id) : (Number(b?.item_id) || 0);
    if (!Number.isNaN(orderA) && !Number.isNaN(orderB) && orderA !== orderB) {
      return orderA - orderB;
    }
    return (Number(a?.item_id) || 0) - (Number(b?.item_id) || 0);
  });
}

export function buildRecordFormFields(formItems, profileId = '') {
  const items = normalizeFormItems(formItems);
  const fieldsWithPermissions = updateDataWithFieldPermissions(items, profileId)
    .map(normalizeRequiredFlag);
  const mergedFields = [...fieldsWithPermissions];

  Object.entries(staticLeadTableColumns).forEach(([staticKey, config]) => {
    const keyName = config?.key_name || staticKey;
    const exists = mergedFields.some((field) => field?.key_name === keyName);
    if (!exists) {
      mergedFields.push({ ...config });
    }
  });

  return sortRecordFieldsByOrder(mergedFields);
}

export function buildRecordFormGroups(formPayload) {
  return formPayload?.group_options ?? formPayload?.groups ?? [];
}

function isStaticDrawerField(field) {
  if (!field) return true;
  if (field.is_static_column === true) return true;
  return Boolean(staticLeadTableColumns[field.key_name]?.is_static_column);
}

function normalizeRequiredFlag(field) {
  const required = field?.is_required ?? field?.isRequired ?? field?.required;
  return {
    ...field,
    is_required: required === true
      || required === 1
      || required === '1'
      || String(required || '').toLowerCase() === 'true',
  };
}

export function isCreatableRecordField(field) {
  if (!field || field.access_level === 'none') return false;
  if (isStaticDrawerField(field) || isLeadIdField(field)) return false;
  if (field.is_primary) return false;
  return true;
}

export function isEditableRecordField(field) {
  if (!field || field.access_level === 'none') return false;
  return !isStaticDrawerField(field) && !isLeadIdField(field);
}

export function buildGroupedRecordFormDataFromFields(
  fieldDefinitions = [],
  formGroups = [],
  record = null
) {
  const sortedDefinitions = sortRecordFieldsByOrder(fieldDefinitions);
  const sourceData = record?.data ?? [];
  const fieldMap = new Map(sourceData.map((item) => [item.key_name, item]));

  const populated = sortedDefinitions.map((field) => {
    const normalizedField = normalizeRequiredFlag(field);
    const source = fieldMap.get(field?.key_name);
    const topLevelValue = record?.[field?.key_name];

    return {
      ...normalizedField,
      value: source?.value ?? topLevelValue ?? normalizedField.value ?? '',
      status_config: source?.status_config ?? normalizedField.status_config ?? null,
      entity_data: source?.entity_data ?? normalizedField.entity_data ?? null,
    };
  });

  return groupLeadItems(populated, formGroups);
}

/**
 * Builds grouped dynamic form data for record create/edit drawer (Leads module parity).
 */
export function buildRecordDynamicFormData(webForm, record = null, profileId = '') {
  if (!webForm) return {};

  const formItems = webForm.leads_form_items ?? webForm.data ?? {};
  const formFields = buildRecordFormFields(formItems, profileId);
  const sourceData = record?.data ?? [];
  const fieldMap = new Map(sourceData.map((item) => [item.key_name, item]));

  const populated = formFields.map((field) => {
    const source = fieldMap.get(field?.key_name);
    const topLevelValue = record?.[field?.key_name];

    return {
      ...normalizeRequiredFlag(field),
      value: source?.value ?? topLevelValue ?? field.value ?? '',
      status_config: source?.status_config ?? field.status_config ?? null,
      entity_data: source?.entity_data ?? field.entity_data ?? null,
    };
  });

  return groupLeadItems(populated, buildRecordFormGroups(webForm));
}

/**
 * True when the drawer has at least one non-static, editable field to render.
 */
export function hasVisibleRecordFormFields(formData, { isCreating = false } = {}) {
  const matches = isCreating ? isCreatableRecordField : isEditableRecordField;
  return Object.values(formData || {}).some(
    (group) => Array.isArray(group) && group.some((field) => matches(field))
  );
}

export function hasVisibleRecordFormFieldDefinitions(fieldDefinitions = [], { isCreating = false } = {}) {
  const matches = isCreating ? isCreatableRecordField : isEditableRecordField;
  return fieldDefinitions.some((field) => matches(field));
}

/** @deprecated Use hasVisibleRecordFormFields */
export function hasEditableRecordFormFields(formData) {
  return hasVisibleRecordFormFields(formData, { isCreating: false });
}
