import React from 'react';
import { Box, Link, Typography } from '@mui/material';
import { parseLeadChatWhatsAppText } from '../../utils/leadChatFormatWhatsAppText';

function renderSegment(segment, index) {
  switch (segment.type) {
    case 'bold':
      return (
        <Box key={index} component="strong" sx={{ fontWeight: 700, color: 'inherit' }}>
          {segment.value}
        </Box>
      );
    case 'italic':
      return (
        <Box key={index} component="em" sx={{ color: 'inherit' }}>
          {segment.value}
        </Box>
      );
    case 'strike':
      return (
        <Box key={index} component="s" sx={{ color: 'inherit' }}>
          {segment.value}
        </Box>
      );
    case 'code':
      return (
        <Box
          key={index}
          component="code"
          sx={{
            fontFamily: 'monospace',
            fontSize: '0.92em',
            px: 0.5,
            borderRadius: 0.5,
            bgcolor: 'action.hover',
            color: 'inherit',
          }}
        >
          {segment.value}
        </Box>
      );
    case 'link':
      return (
        <Link
          key={index}
          href={segment.value}
          target="_blank"
          rel="noopener noreferrer"
          underline="hover"
          sx={{ color: 'inherit', fontWeight: 500 }}
        >
          {segment.value}
        </Link>
      );
    case 'break':
      return <br key={index} />;
    default:
      return <React.Fragment key={index}>{segment.value}</React.Fragment>;
  }
}

export default function LeadFormattedText({ text, variant = 'body2', sx = {} }) {
  if (!text) return null;

  const segments = parseLeadChatWhatsAppText(text);

  return (
    <Typography
      variant={variant}
      component="div"
      sx={{
        whiteSpace: 'pre-wrap',
        wordBreak: 'break-word',
        fontSize: '0.8125rem',
        lineHeight: 1.45,
        ...sx,
      }}
    >
      {segments.map(renderSegment)}
    </Typography>
  );
}
