import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Alert, Box, useMediaQuery, useTheme } from '@mui/material';
import ViewColumnOutlinedIcon from '@mui/icons-material/ViewColumnOutlined';
import { Button, Dialog } from '../../../../../components/ui';
import { useFeatureTheme } from '../../../../../theme/hooks/useFeatureTheme';
import useStatusLogs from '../../hooks/useStatusLogs';
import useStatusLogTemplate from '../../hooks/useStatusLogTemplate';
import { RECORD_COPY } from '../../constants/recordCopy';
import { resolveBotNumber, resolveLeadIdForStatusLogs } from '../../utils/statusLogUtils';
import StatusLogPayloadColumnsMenu from './StatusLogPayloadColumnsMenu';
import StatusLogsTable from './StatusLogsTable';
import StatusLogTemplatePanel from './template/StatusLogTemplatePanel';

export default function StatusLogsModal({
  open,
  onClose,
  selectedRow,
}) {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const { semantic } = useFeatureTheme();

  const leadId = useMemo(
    () => resolveLeadIdForStatusLogs(selectedRow),
    [selectedRow]
  );

  const botNumber = useMemo(() => resolveBotNumber(selectedRow), [selectedRow]);
  const copy = RECORD_COPY.statusLogs;

  const {
    rows,
    isLoading,
    error,
    payloadKeys,
    selectedPayloadFields,
    togglePayloadField,
    setAllPayloadFields,
  } = useStatusLogs({ open, leadId });

  const templateState = useStatusLogTemplate({ botNumber });
  const {
    selectedTemplate,
    templateTab,
    templateDateSummary,
    templateUsers,
    templateUsersTotal,
    selectedTemplateDate,
    templateStartDate,
    templateEndDate,
    isTemplateLoading,
    isUsersLoading,
    templateDetailKeys,
    openTemplate,
    resetTemplateState,
    handleDateClick,
    handleTabChange,
    handleDateRangeChange,
    clearDateRange,
  } = templateState;

  const [payloadAnchorEl, setPayloadAnchorEl] = useState(null);
  const view = selectedTemplate ? 'template' : 'list';

  useEffect(() => {
    if (!open) {
      resetTemplateState();
      setPayloadAnchorEl(null);
    }
  }, [open, resetTemplateState]);

  const handleTemplateClick = useCallback(async (row, templateName) => {
    await openTemplate({
      row,
      templateName,
      sentDate: selectedRow?.updated_at || selectedRow?.created_at,
      botNumber,
    });
  }, [botNumber, openTemplate, selectedRow?.created_at, selectedRow?.updated_at]);

  const handleBackToLogs = useCallback(() => {
    resetTemplateState();
  }, [resetTemplateState]);

  const handleStartDateChange = useCallback(async (startDate, endDate) => {
    if (startDate && endDate && startDate > endDate) {
      await handleDateRangeChange({ startDate, endDate: '' });
      return;
    }
    await handleDateRangeChange({ startDate, endDate });
  }, [handleDateRangeChange]);

  const handleEndDateChange = useCallback(async (startDate, endDate) => {
    if (!endDate) return;
    await handleDateRangeChange({ startDate, endDate });
  }, [handleDateRangeChange]);

  return (
    <>
      <Dialog
        open={open}
        onClose={onClose}
        title={copy.title}
        maxWidth="xl"
        fullScreen={isMobile}
        contentSx={{
          px: { xs: 2, sm: 3 },
          py: { xs: 1.5, sm: 2 },
          display: 'flex',
          flexDirection: 'column',
          minHeight: 0,
          maxHeight: isMobile ? 'none' : 'min(85vh, 720px)',
          overflow: 'hidden',
        }}
      >
        {error ? (
          <Alert severity="error" sx={{ mb: 2, flexShrink: 0 }}>
            {error}
          </Alert>
        ) : null}

        {view === 'list' ? (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              minHeight: 0,
              flex: 1,
            }}
          >
            {/* <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'flex-end',
                flexWrap: 'wrap',
                gap: 1,
                mb: 1.5,
                flexShrink: 0,
              }}
            >
              <Button
                variant="outline"
                size="sm"
                icon={<ViewColumnOutlinedIcon fontSize="small" />}
                disabled={payloadKeys.length === 0}
                onClick={(event) => setPayloadAnchorEl(event.currentTarget)}
                sx={{ width: { xs: '100%', sm: 'auto' } }}
              >
                {copy.payloadColumns}
              </Button>
            </Box> */}

            <Box
              sx={{
                flex: 1,
                minHeight: 0,
                minWidth: 0,
                width: '100%',
                border: `1px solid ${semantic.borders.border}`,
                borderRadius: 2,
                overflow: 'hidden',
                bgcolor: semantic.surfaces.surface,
              }}
            >
              <StatusLogsTable
                rows={rows}
                loading={isLoading}
                selectedPayloadFields={selectedPayloadFields}
                onTemplateClick={handleTemplateClick}
                isMobile={isMobile}
              />
            </Box>
          </Box>
        ) : (
          <Box
            sx={{
              flex: 1,
              minHeight: 0,
              minWidth: 0,
              overflowY: 'auto',
              WebkitOverflowScrolling: 'touch',
            }}
          >
            <StatusLogTemplatePanel
              selectedTemplate={selectedTemplate}
              templateTab={templateTab}
              templateDateSummary={templateDateSummary}
              templateUsers={templateUsers}
              templateUsersTotal={templateUsersTotal}
              selectedTemplateDate={selectedTemplateDate}
              templateStartDate={templateStartDate}
              templateEndDate={templateEndDate}
              isTemplateLoading={isTemplateLoading}
              isUsersLoading={isUsersLoading}
              templateDetailKeys={templateDetailKeys}
              statusRows={rows}
              isMobile={isMobile}
              onBack={handleBackToLogs}
              onTabChange={handleTabChange}
              onDateClick={handleDateClick}
              onStartDateChange={handleStartDateChange}
              onEndDateChange={handleEndDateChange}
              onClearRange={clearDateRange}
            />
          </Box>
        )}
      </Dialog>

      <StatusLogPayloadColumnsMenu
        anchorEl={payloadAnchorEl}
        onClose={() => setPayloadAnchorEl(null)}
        payloadKeys={payloadKeys}
        selectedPayloadFields={selectedPayloadFields}
        onToggleField={togglePayloadField}
        onToggleAll={setAllPayloadFields}
      />
    </>
  );
}
