import React, { useMemo } from 'react';
import AssessmentOutlinedIcon from '@mui/icons-material/AssessmentOutlined';
import DeleteOutlineOutlinedIcon from '@mui/icons-material/DeleteOutlineOutlined';
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';
import GraphicEqOutlinedIcon from '@mui/icons-material/GraphicEqOutlined';
import ManageAccountsOutlinedIcon from '@mui/icons-material/ManageAccountsOutlined';
import PhoneOutlinedIcon from '@mui/icons-material/PhoneOutlined';
import PhotoLibraryOutlinedIcon from '@mui/icons-material/PhotoLibraryOutlined';
import SendOutlinedIcon from '@mui/icons-material/SendOutlined';
import AssignmentIndOutlinedIcon from '@mui/icons-material/AssignmentIndOutlined';
import ChatOutlinedIcon from '@mui/icons-material/ChatOutlined';
import { RECORD_COPY } from '../constants/recordCopy';
import { ROW_MODAL } from '../constants/rowModalKeys';
import { resolveLeadPhoneFromRow } from '../utils/leadTemplateSendUtils';
import { hasAudioSummaryTranscript } from '../utils/recordInteractiveColumnUtils';

const actionIconProps = { sx: { fontSize: 16 } };

export function shouldShowRowSendTemplate({
  canSendTemplate = false,
  selectedCount = 0,
  isRowSelected = false,
} = {}) {
  if (!canSendTemplate) return false;
  if (selectedCount > 1 && isRowSelected) return false;
  return true;
}

export function shouldShowRowAssign({
  canAssignLead = false,
  selectedCount = 0,
  isRowSelected = false,
} = {}) {
  if (!canAssignLead) return false;
  if (selectedCount > 1 && isRowSelected) return false;
  return true;
}

export function shouldShowRowChat({ canUseLeadChat = false, row } = {}) {
  if (!canUseLeadChat || !row) return false;
  return resolveLeadPhoneFromRow(row).valid;
}

/** System field — show when transcript exists; no record-action grant. */
export function shouldShowRowAudioSummary({ row } = {}) {
  if (!row) return false;
  return hasAudioSummaryTranscript(row);
}

export function buildRowActions({
  row,
  permissions = {},
  selectedCount = 0,
  isRowSelected = false,
  onEdit,
  onDelete,
  onOpenRowModal,
  onOpenAudioSummary,
  onOpenLeadChat,
}) {
  const rawLead = row?._rawLead ?? row;

  return [
    {
      id: 'manage-record',
      label: RECORD_COPY.rowActions.manageRecord,
      icon: <ManageAccountsOutlinedIcon {...actionIconProps} />,
      visible: permissions.canManageRecord,
      onClick: () => onOpenRowModal?.(ROW_MODAL.MANAGE, row),
    },
    {
      id: 'assign-lead',
      label: RECORD_COPY.rowActions.assignLead,
      icon: <AssignmentIndOutlinedIcon {...actionIconProps} />,
      visible: shouldShowRowAssign({
        canAssignLead: permissions.canAssignLead,
        selectedCount,
        isRowSelected,
      }),
      onClick: () => onOpenRowModal?.(ROW_MODAL.ASSIGN, row),
    },
    {
      id: 'status-logs',
      label: RECORD_COPY.rowActions.statusLogs,
      icon: <AssessmentOutlinedIcon {...actionIconProps} />,
      visible: permissions.canViewStatusLogs,
      onClick: () => onOpenRowModal?.(ROW_MODAL.STATUS_LOGS, row),
    },
    {
      id: 'send-template',
      label: RECORD_COPY.rowActions.sendTemplate,
      icon: <SendOutlinedIcon {...actionIconProps} />,
      visible: shouldShowRowSendTemplate({
        canSendTemplate: permissions.canSendTemplate,
        selectedCount,
        isRowSelected,
      }),
      onClick: () => onOpenRowModal?.(ROW_MODAL.SEND_TEMPLATE, row),
    },
    {
      id: 'images',
      label: RECORD_COPY.rowActions.images,
      icon: <PhotoLibraryOutlinedIcon {...actionIconProps} />,
      visible: permissions.canViewImages,
      onClick: () => onOpenRowModal?.(ROW_MODAL.IMAGES, row),
    },
    {
      id: 'quick-call',
      label: RECORD_COPY.rowActions.quickCall,
      icon: <PhoneOutlinedIcon {...actionIconProps} />,
      visible: permissions.canQuickCall,
      onClick: () => onOpenRowModal?.(ROW_MODAL.QUICK_CALL, row),
    },
    {
      id: 'chat',
      label: RECORD_COPY.rowActions.chat,
      icon: <ChatOutlinedIcon {...actionIconProps} />,
      visible: shouldShowRowChat({ canUseLeadChat: permissions.canUseLeadChat, row }),
      onClick: () => onOpenLeadChat?.(row),
    },
    {
      id: 'audio-summary',
      label: RECORD_COPY.rowActions.audioSummary,
      icon: <GraphicEqOutlinedIcon {...actionIconProps} />,
      visible: shouldShowRowAudioSummary({ row }),
      onClick: () => onOpenAudioSummary?.(row),
    },
    {
      id: 'edit',
      label: RECORD_COPY.editRecord,
      icon: <EditOutlinedIcon {...actionIconProps} />,
      visible: permissions.canEdit,
      onClick: () => onEdit?.(rawLead),
    },
    {
      id: 'delete',
      label: RECORD_COPY.deleteRecord,
      icon: <DeleteOutlineOutlinedIcon {...actionIconProps} />,
      visible: permissions.canDelete,
      destructive: true,
      onClick: () => onDelete?.(rawLead),
    },
  ];
}

export default function useRowActions(options) {
  return useMemo(
    () => buildRowActions(options),
    [
      options.onDelete,
      options.onEdit,
      options.onOpenAudioSummary,
      options.onOpenLeadChat,
      options.onOpenRowModal,
      options.permissions,
      options.row,
      options.selectedCount,
      options.isRowSelected,
    ]
  );
}
