import React, { useEffect } from 'react';
import { Box, Fab, Tooltip } from '@mui/material';
import ChatOutlinedIcon from '@mui/icons-material/ChatOutlined';
import { unlockMessageSound } from '../../../../../shared/notifications';
import LeadChatPanelContent from './LeadChatPanelContent';
import useLeadChatSx from '../hooks/useLeadChatSx';
import { getConversationDisplayName } from '../utils/leadChatIdentity';

export default function LeadChatWidget({
  open,
  isMinimized,
  baseContext,
  formPayload,
  canSendTemplate = false,
  onOpenSendTemplate,
  onClose,
  onMinimize,
  onRestore,
}) {
  const sx = useLeadChatSx();

  useEffect(() => {
    const unlock = () => unlockMessageSound();
    document.addEventListener('pointerdown', unlock, { once: true });
    document.addEventListener('keydown', unlock, { once: true });

    return () => {
      document.removeEventListener('pointerdown', unlock);
      document.removeEventListener('keydown', unlock);
    };
  }, []);

  if (!open || !baseContext) return null;

  const displayName = getConversationDisplayName({
    whatsappName: baseContext.profileName || baseContext.whatsappName,
    phoneNumber: baseContext.phoneNumber,
    leadId: baseContext.leadId,
  });

  return (
    <>
      {isMinimized ? (
        <Tooltip title={`Chat with ${displayName}`}>
          <Fab
            color="primary"
            aria-label="Open chat"
            onClick={onRestore}
            sx={sx.fab}
          >
            <ChatOutlinedIcon />
          </Fab>
        </Tooltip>
      ) : null}
      <Box
        sx={{
          ...sx.widget,
          display: isMinimized ? 'none' : sx.widget?.display ?? 'flex',
        }}
      >
        <LeadChatPanelContent
          open={open}
          baseContext={baseContext}
          formPayload={formPayload}
          canSendTemplate={canSendTemplate}
          onOpenSendTemplate={onOpenSendTemplate}
          onClose={onClose}
        />
      </Box>
    </>
  );
}
