import React, { useMemo } from 'react';
import { Box, Checkbox, FormControlLabel, FormHelperText, Typography } from '@mui/material';
import FileInput from '../../../../components/Shared/FileUploadPreview/FileInput.jsx';
import { useFeatureTheme } from '../../../../theme/hooks/useFeatureTheme';
import {
  getLeadHeaderAcceptValue,
  needsLeadTemplateHeaderMedia,
} from '../utils/leadTemplateHeaderSend';

function headerUploadHint(copy, format) {
  if (format === 'IMAGE') return copy.direct.headerUploadHintImage;
  if (format === 'VIDEO') return copy.direct.headerUploadHintVideo;
  if (format === 'DOCUMENT') return copy.direct.headerUploadHintDocument;
  return '';
}

export default function LeadSendTemplateHeaderSection({
  copy,
  template,
  headerFormat,
  headerFile,
  useTemplateHeaderMedia,
  headerValidationError = '',
  disabled = false,
  onHeaderFileSelect,
  onHeaderFileRemove,
  onUseTemplateHeaderChange,
}) {
  const { semantic, typography } = useFeatureTheme();

  const showSection = useMemo(
    () => needsLeadTemplateHeaderMedia(template),
    [template]
  );

  if (!showSection || !headerFormat) return null;

  const uploadHint = headerUploadHint(copy, headerFormat);
  const hasTemplateMedia = Boolean(template?.media?.header);

  return (
    <Box sx={{ mt: 2.5, mb: 2 }}>
      <Typography
        sx={{
          fontSize: typography.fontSizeSm,
          fontWeight: 700,
          color: semantic.text.primary,
          mb: 1.25,
        }}
      >
        {copy.direct.headerSectionTitle(headerFormat)}
      </Typography>

      {!useTemplateHeaderMedia ? (
        <Box sx={{ mb: hasTemplateMedia ? 1.5 : 0 }}>
          <FileInput
            onFileSelect={onHeaderFileSelect}
            onFileRemove={onHeaderFileRemove}
            file={headerFile}
            setFile={() => {}}
            accept={getLeadHeaderAcceptValue(headerFormat)}
          />
          {uploadHint ? (
            <FormHelperText sx={{ mt: 0.75, mx: 0 }}>{uploadHint}</FormHelperText>
          ) : null}
        </Box>
      ) : null}

      {headerValidationError && !useTemplateHeaderMedia ? (
        <FormHelperText error sx={{ mt: 0.5, mb: hasTemplateMedia ? 1 : 0 }}>
          {headerValidationError}
        </FormHelperText>
      ) : null}

      {hasTemplateMedia ? (
        <FormControlLabel
          sx={{
            mt: 0,
            alignItems: 'flex-start',
            '& .MuiFormControlLabel-label': {
              fontSize: typography.fontSizeSm,
              color: semantic.text.primary,
              lineHeight: 1.45,
            },
          }}
          control={
            <Checkbox
              checked={useTemplateHeaderMedia}
              onChange={(event) => onUseTemplateHeaderChange(event.target.checked)}
              disabled={disabled}
              sx={{ pt: 0.25 }}
            />
          }
          label={copy.direct.useTemplateHeaderLabel(headerFormat)}
        />
      ) : null}

      {headerValidationError && useTemplateHeaderMedia ? (
        <FormHelperText error sx={{ mt: 0.5 }}>
          {headerValidationError}
        </FormHelperText>
      ) : null}
    </Box>
  );
}
